@@ -0,0 +1,126 @@
+import { ensureDrawingControl, deactivateDrawing, getTdControl } from './drawing.js';
+
+export interface DrawingControlsAPI {
+  withDrawingControl: (callback: Function) => void;
+  setDrawingControlReady: (ready: boolean) => void;
+}
+
+export function initDrawingControls(map: any): DrawingControlsAPI {
+  const drawingReadyCallbacks: Function[] = [];
+  let drawingControlReady = Boolean(getTdControl());
+  let drawingControlInitPending = false;
+  let cleanupDrawingInit: Function | null = null;
+
+  const flushDrawingReadyQueue = () => {
+    const control = getTdControl();
+    if (!control) {
+      drawingControlReady = false;
+      drawingControlInitPending = false;
+      return;
+    }
+    drawingControlReady = true;
+    drawingControlInitPending = false;
+    try {
+      deactivateDrawing();
+    } catch (_) {
+      /* ignore drawing deactivate errors */
+    }
+    while (drawingReadyCallbacks.length) {
+      const cb = drawingReadyCallbacks.shift();
+      if (typeof cb !== 'function') continue;
+      try {
+        cb(control);
+      } catch (_) {
+        /* ignore drawing ready callback errors */
+      }
+    }
+  };
+
+  const isMapStyleReady = () => {
+    try {
+      if (typeof map.isStyleLoaded === 'function') return map.isStyleLoaded();
+    } catch (_) {
+      /* ignore style ready detection errors */
+    }
+    try {
+      if (typeof map.loaded === 'function') return map.loaded();
+    } catch (_) {
+      /* ignore load ready detection errors */
+    }
+    return true;
+  };
+
+  const ensureRoutingDrawingControl = () => {
+    const existingControl = getTdControl();
+    if (existingControl) {
+      if (typeof cleanupDrawingInit === 'function') cleanupDrawingInit();
+      drawingControlInitPending = false;
+      flushDrawingReadyQueue();
+      return;
+    }
+    if (isMapStyleReady()) {
+      if (typeof cleanupDrawingInit === 'function') cleanupDrawingInit();
+      drawingControlInitPending = false;
+      ensureDrawingControl(map, 'top-left');
+      flushDrawingReadyQueue();
+      return;
+    }
+    if (drawingControlInitPending) return;
+    drawingControlInitPending = true;
+    let fired = false;
+    const onReady = () => {
+      if (fired) return;
+      fired = true;
+      if (typeof cleanupDrawingInit === 'function') cleanupDrawingInit();
+      ensureDrawingControl(map, 'top-left');
+      flushDrawingReadyQueue();
+    };
+    if (typeof map.once === 'function') {
+      map.once('styledata', onReady);
+      map.once('load', onReady);
+      cleanupDrawingInit = () => {
+        if (typeof map.off === 'function') {
+          map.off('styledata', onReady);
+          map.off('load', onReady);
+        }
+        cleanupDrawingInit = null;
+      };
+    } else if (typeof map.on === 'function' && typeof map.off === 'function') {
+      map.on('styledata', onReady);
+      map.on('load', onReady);
+      cleanupDrawingInit = () => {
+        map.off('styledata', onReady);
+        map.off('load', onReady);
+        cleanupDrawingInit = null;
+      };
+    } else {
+      onReady();
+    }
+  };
+
+  const withDrawingControl = (callback: Function) => {
+    const control = getTdControl();
+    if (control) {
+      drawingControlReady = true;
+      if (typeof callback === 'function') {
+        try {
+          callback(control);
+        } catch (_) {
+          /* ignore drawing ready callback errors */
+        }
+      }
+      return;
+    }
+    if (typeof callback === 'function') drawingReadyCallbacks.push(callback);
+    ensureRoutingDrawingControl();
+  };
+
+  const setDrawingControlReady = (ready: boolean) => {
+    drawingControlReady = ready;
+  };
+
+  return {
+    withDrawingControl,
+    setDrawingControlReady
+  };
+}
