+export function setLayerCheckboxLoadingState(layerControlsEl: HTMLElement | null, loading: boolean) {
+  if (!layerControlsEl) return;
+  const checkboxes = layerControlsEl.querySelectorAll<HTMLInputElement>('input[type="checkbox"][data-kml-id]');
+  checkboxes.forEach(cb => {
+    if (!cb) return;
+    if (loading) {
+      if (cb.dataset.loadingDisabled) return;
+      cb.dataset.loadingDisabled = cb.disabled ? 'permanent' : 'temporary';
+      if (!cb.disabled) cb.disabled = true;
+    } else if (cb.dataset.loadingDisabled) {
+      if (cb.dataset.loadingDisabled === 'temporary') {
+        cb.disabled = false;
+      }
+      delete cb.dataset.loadingDisabled;
+    }
+  });
+}
+
+export function setModifyButtonLoadingState(createRuleBtn: HTMLElement | null, loading: boolean) {
+  if (!createRuleBtn) return;
+  if (loading) {
+    if (createRuleBtn.dataset.loadingDisabled) return;
+    createRuleBtn.dataset.loadingDisabled = autonomousStateStore.getState().isCreateRuleDisabled ? 'permanent' : 'temporary';
+    autonomousStateStore.setState({ isCreateRuleDisabled: true });
+  } else if (createRuleBtn.dataset.loadingDisabled) {
+    const mode = createRuleBtn.dataset.loadingDisabled;
+    delete createRuleBtn.dataset.loadingDisabled;
+    if (mode === 'temporary') {
+      autonomousStateStore.setState({ isCreateRuleDisabled: false });
+    }
+  }
+}
+
+export function setPublishButtonState(createMapBtn: HTMLElement | null, busy: boolean, translations: any) {
+  if (!createMapBtn) return;
+  if (busy) {
+    autonomousStateStore.setState({ isCreateMapPositive: false, isCreateMapDisabled: true });
+    const busyText =
+      (translations && (translations.generating || translations.publishing)) ||
+      'Publishing…';
+    createMapBtn.textContent = busyText;
+    return;
+  }
+  autonomousStateStore.setState({ isCreateMapPositive: true, isCreateMapDisabled: false });
+  const defaultLabel =
+    (translations && translations.publish_rules) ||
+    createMapBtn.dataset.defaultLabel ||
+    'Publish Rules';
+  createMapBtn.textContent = defaultLabel;
+}
+
+export function setSubActionsVisible(visible: boolean) {
+  autonomousStateStore.setState({ isRuleSubActionsVisible: visible });
+}
+
+export function updateCreateButtonLabel(options: {
+  createRuleBtn: HTMLElement | null,
+  createRuleText: HTMLElement | null,
+  selectionActive: boolean,
+  hasHighlightedRule: boolean,
+  translations: any
+}) {
+  const { createRuleBtn, createRuleText, selectionActive, hasHighlightedRule, translations } = options;
+  if (!createRuleBtn) return;
+  let text;
+  if (selectionActive) {
+    text = translations?.select_objects || 'Select Objects';
+  } else if (hasHighlightedRule) {
+    text = translations?.modify_rule || 'Modify Rule';
+  } else {
+    text = translations?.create_rule || 'Create Rule';
+  }
+  if (createRuleText) {
+    createRuleText.textContent = text;
+  } else {
+    createRuleBtn.textContent = text;
+  }
+}
+
+export function updateConfirmSelectionLabel(confirmSelectionBtn: HTMLElement | null, isEditing: boolean) {
+  if (!confirmSelectionBtn) return;
+  confirmSelectionBtn.textContent = isEditing ? 'Update' : 'Create';
+}
